INSERT INTO "leagues" ("id", "code", "name", "slug", "weekday", "default_venue_id", "sort", "active", "kind", "category_id", "status", "start_time", "end_time", "schedule_label", "description", "age_min", "age_max", "cap_players", "price_cents", "allow_free_agents") SELECT 'c8630af9-6661-8f18-a9fa-8ed5c3729115', 'ADP', 'Adult Development Program (ADP)', 'adult-development-program-adp', 6, NULL, 1, 0, 'development', 'cat_adult_training', 'draft', '20:00', '22:00', 'Saturdays 8–10pm at Tempe, Sundays 1–3pm at Burwood', '{"blocks":[{"type":"paragraph","content":[{"type":"text","text":"Coached sessions for adults (18+) who want to learn volleyball, improve their technique or get ready for a social league. Beginners are welcome."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"When and where"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Saturdays, 8–10pm: Robyn Webster Sports Centre, Tempe"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Sundays, 1–3pm: MLC School, Burwood"}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"What we cover"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Passing (dig), setting, attacking (spike), blocking, serving and serve receive"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Court movement and positioning"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Game strategy and teamwork"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Confidence on court for new players"}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"Every player needs a current Volleyball NSW recreational membership, through our club (Sydney Uni, USYD). "},{"type":"text","text":"Register with Volleyball NSW","marks":[{"type":"link","attrs":{"href":"https://www.revolutionise.com.au/usyd/registration/","target":"_blank"}}]},{"type":"text","text":" once your spot is confirmed. Already a member through another club? Choose “Renew” on that page and add USYD to your profile."}]}],"html":"<p>Coached sessions for adults (18+) who want to learn volleyball, improve their technique or get ready for a social league. Beginners are welcome.</p><h2>When and where</h2><ul><li><p>Saturdays, 8–10pm: Robyn Webster Sports Centre, Tempe</p></li><li><p>Sundays, 1–3pm: MLC School, Burwood</p></li></ul><h2>What we cover</h2><ul><li><p>Passing (dig), setting, attacking (spike), blocking, serving and serve receive</p></li><li><p>Court movement and positioning</p></li><li><p>Game strategy and teamwork</p></li><li><p>Confidence on court for new players</p></li></ul><p>Every player needs a current Volleyball NSW recreational membership, through our club (Sydney Uni, USYD). <a href=\"https://www.revolutionise.com.au/usyd/registration/\" target=\"_blank\" rel=\"noopener\">Register with Volleyball NSW</a> once your spot is confirmed. Already a member through another club? Choose “Renew” on that page and add USYD to your profile.</p>"}', 18, NULL, NULL, NULL, 1 WHERE NOT EXISTS (SELECT 1 FROM "leagues" WHERE "id" = 'c8630af9-6661-8f18-a9fa-8ed5c3729115' OR "code" = 'ADP' OR "slug" = 'adult-development-program-adp') AND EXISTS (SELECT 1 FROM "categories" WHERE "id" = 'cat_adult_training');
