INSERT INTO "leagues" ("id", "code", "name", "slug", "weekday", "default_venue_id", "sort", "active", "kind", "category_id", "status", "start_time", "end_time", "schedule_label", "description", "age_min", "age_max", "cap_players", "price_cents", "allow_free_agents") SELECT '537ffe3e-44f5-8336-82fe-53edc26758c8', 'SCT', 'Scrim & Coached Training', 'scrim-and-coached-training', 5, (SELECT "id" FROM "venues" WHERE "slug" = 'robyn-webster-sports-centre'), 2, 0, 'training', 'cat_adult_training', 'draft', '20:00', '22:00', NULL, '{"blocks":[{"type":"paragraph","content":[{"type":"text","text":"Court time for adults who want more games between league nights: open scrimmage, plus coached sessions. Come on your own or bring a team of six or more."}]},{"type":"paragraph","content":[{"type":"text","text":"Bookings are essential. Pick a session below and we’ll confirm your place by email."}]},{"type":"paragraph","content":[{"type":"text","text":"Every player needs a current Volleyball NSW recreational membership, through our club (Sydney Uni, USYD). "},{"type":"text","text":"Register with Volleyball NSW","marks":[{"type":"link","attrs":{"href":"https://www.revolutionise.com.au/usyd/registration/","target":"_blank"}}]},{"type":"text","text":" once your spot is confirmed. Already a member through another club? Choose “Renew” on that page and add USYD to your profile."}]}],"html":"<p>Court time for adults who want more games between league nights: open scrimmage, plus coached sessions. Come on your own or bring a team of six or more.</p><p>Bookings are essential. Pick a session below and we’ll confirm your place by email.</p><p>Every player needs a current Volleyball NSW recreational membership, through our club (Sydney Uni, USYD). <a href=\"https://www.revolutionise.com.au/usyd/registration/\" target=\"_blank\" rel=\"noopener\">Register with Volleyball NSW</a> once your spot is confirmed. Already a member through another club? Choose “Renew” on that page and add USYD to your profile.</p>"}', NULL, NULL, NULL, NULL, 1 WHERE NOT EXISTS (SELECT 1 FROM "leagues" WHERE "id" = '537ffe3e-44f5-8336-82fe-53edc26758c8' OR "code" = 'SCT' OR "slug" = 'scrim-and-coached-training') AND EXISTS (SELECT 1 FROM "categories" WHERE "id" = 'cat_adult_training');
