INSERT INTO "leagues" ("id", "code", "name", "slug", "weekday", "default_venue_id", "sort", "active", "kind", "category_id", "status", "start_time", "end_time", "schedule_label", "description", "age_min", "age_max", "cap_players", "price_cents", "allow_free_agents") SELECT '5eb123f0-0c26-8b6e-a6a4-aaef16ae03dc', 'TCT', 'Thursday Night Casual Training', 'thursday-night-casual-training', 4, (SELECT "id" FROM "venues" WHERE "slug" = 'robyn-webster-sports-centre'), 3, 0, 'training', 'cat_adult_training', 'draft', '20:00', '22:00', NULL, '{"blocks":[{"type":"paragraph","content":[{"type":"text","text":"Casual training sessions on Thursday evenings at the Robyn Webster Sports Centre in Tempe, run with the Sydney Uni Volleyball Club."}]},{"type":"paragraph","content":[{"type":"text","text":"Each session takes up to 40 people, first come, first served, so book your place below. The session fee is paid in cash on the night (there’s no ATM or EFTPOS at the venue)."}]}],"html":"<p>Casual training sessions on Thursday evenings at the Robyn Webster Sports Centre in Tempe, run with the Sydney Uni Volleyball Club.</p><p>Each session takes up to 40 people, first come, first served, so book your place below. The session fee is paid in cash on the night (there’s no ATM or EFTPOS at the venue).</p>"}', NULL, NULL, 40, 1500, 1 WHERE NOT EXISTS (SELECT 1 FROM "leagues" WHERE "id" = '5eb123f0-0c26-8b6e-a6a4-aaef16ae03dc' OR "code" = 'TCT' OR "slug" = 'thursday-night-casual-training') AND EXISTS (SELECT 1 FROM "categories" WHERE "id" = 'cat_adult_training');
INSERT INTO "audit_log" ("id", "at", "actor_user_id", "action", "target_type", "target_id", "before", "after", "ip") SELECT lower(hex(randomblob(16))), strftime('%Y-%m-%dT%H:%M:%fZ', 'now'), NULL, 'programme.create', 'programme', '823290c2-d73a-8e18-9975-eaaa9df9e978', NULL, '{"name":"Junior Development Program (JDP)","code":"JDP","slug":"junior-development-program-jdp","kind":"development","status":"draft","categoryId":"cat_juniors","description":"(rich text)","source":"scripts/content (content map)"}', NULL WHERE NOT EXISTS (SELECT 1 FROM "leagues" WHERE "id" = '823290c2-d73a-8e18-9975-eaaa9df9e978' OR "code" = 'JDP' OR "slug" = 'junior-development-program-jdp') AND EXISTS (SELECT 1 FROM "categories" WHERE "id" = 'cat_juniors');
INSERT INTO "leagues" ("id", "code", "name", "slug", "weekday", "default_venue_id", "sort", "active", "kind", "category_id", "status", "start_time", "end_time", "schedule_label", "description", "age_min", "age_max", "cap_players", "price_cents", "allow_free_agents") SELECT '823290c2-d73a-8e18-9975-eaaa9df9e978', 'JDP', 'Junior Development Program (JDP)', 'junior-development-program-jdp', 1, NULL, 1, 0, 'development', 'cat_juniors', 'draft', '18:00', '20:00', 'Mondays 6–8pm at Five Dock, Fridays 8–10pm at Tempe', '{"blocks":[{"type":"paragraph","content":[{"type":"text","text":"VolleyJoeys, our Junior Development Program, is for players aged 12 to 17 who want to learn the fundamentals of volleyball or work towards playing in competitions."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"When and where"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Mondays, 6–8pm: Five Dock Leisure Centre"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Fridays, 8–10pm: Robyn Webster Sports Centre, Tempe"}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"All our coaches hold a current Working With Children Check."}]},{"type":"paragraph","content":[{"type":"text","text":"Enrol for a whole term below. A parent or guardian fills in the form for players under 18."}]},{"type":"paragraph","content":[{"type":"text","text":"Every player needs a current Volleyball NSW recreational membership, through our club (Sydney Uni, USYD). "},{"type":"text","text":"Register with Volleyball NSW","marks":[{"type":"link","attrs":{"href":"https://www.revolutionise.com.au/usyd/registration/","target":"_blank"}}]},{"type":"text","text":" once your spot is confirmed. Already a member through another club? Choose “Renew” on that page and add USYD to your profile."}]}],"html":"<p>VolleyJoeys, our Junior Development Program, is for players aged 12 to 17 who want to learn the fundamentals of volleyball or work towards playing in competitions.</p><h2>When and where</h2><ul><li><p>Mondays, 6–8pm: Five Dock Leisure Centre</p></li><li><p>Fridays, 8–10pm: Robyn Webster Sports Centre, Tempe</p></li></ul><p>All our coaches hold a current Working With Children Check.</p><p>Enrol for a whole term below. A parent or guardian fills in the form for players under 18.</p><p>Every player needs a current Volleyball NSW recreational membership, through our club (Sydney Uni, USYD). <a href=\"https://www.revolutionise.com.au/usyd/registration/\" target=\"_blank\" rel=\"noopener\">Register with Volleyball NSW</a> once your spot is confirmed. Already a member through another club? Choose “Renew” on that page and add USYD to your profile.</p>"}', 12, 17, NULL, NULL, 1 WHERE NOT EXISTS (SELECT 1 FROM "leagues" WHERE "id" = '823290c2-d73a-8e18-9975-eaaa9df9e978' OR "code" = 'JDP' OR "slug" = 'junior-development-program-jdp') AND EXISTS (SELECT 1 FROM "categories" WHERE "id" = 'cat_juniors');
INSERT INTO "audit_log" ("id", "at", "actor_user_id", "action", "target_type", "target_id", "before", "after", "ip") SELECT lower(hex(randomblob(16))), strftime('%Y-%m-%dT%H:%M:%fZ', 'now'), NULL, 'programme.create', 'programme', '69d527f4-23db-8a7c-a65c-03b6a8c17e67', NULL, '{"name":"Junior Rep Teams","code":"JREP","slug":"junior-rep-teams","kind":"development","status":"draft","categoryId":"cat_juniors","description":"(rich text)","source":"scripts/content (content map)"}', NULL WHERE NOT EXISTS (SELECT 1 FROM "leagues" WHERE "id" = '69d527f4-23db-8a7c-a65c-03b6a8c17e67' OR "code" = 'JREP' OR "slug" = 'junior-rep-teams') AND EXISTS (SELECT 1 FROM "categories" WHERE "id" = 'cat_juniors');
INSERT INTO "leagues" ("id", "code", "name", "slug", "weekday", "default_venue_id", "sort", "active", "kind", "category_id", "status", "start_time", "end_time", "schedule_label", "description", "age_min", "age_max", "cap_players", "price_cents", "allow_free_agents") SELECT '69d527f4-23db-8a7c-a65c-03b6a8c17e67', 'JREP', 'Junior Rep Teams', 'junior-rep-teams', 1, (SELECT "id" FROM "venues" WHERE "slug" = 'five-dock-leisure-centre'), 2, 0, 'development', 'cat_juniors', 'draft', '18:00', '20:00', NULL, '{"blocks":[{"type":"paragraph","content":[{"type":"text","text":"Tempe Volleyball and the Sydney Uni Volleyball Club (USYD) select junior teams to play in the Junior Sydney Volleyball League against other clubs, with qualified coaches, weekly training and club uniforms for rep players."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"What selected players commit to"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"A weekly league game through the season, at Sydney Olympic Park"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Weekly coached training, which is an essential part of the program"}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"Teams are picked at selection trials before each season. Register your interest below and we’ll be in touch about trial dates."}]},{"type":"paragraph","content":[{"type":"text","text":"Rep players need a "},{"type":"text","text":"full","marks":[{"type":"bold"}]},{"type":"text","text":" Volleyball NSW membership through USYD. "},{"type":"text","text":"Register with Volleyball NSW","marks":[{"type":"link","attrs":{"href":"https://www.revolutionise.com.au/usyd/registration/","target":"_blank"}}]},{"type":"text","text":" once selected. All our coaches hold a current Working With Children Check."}]}],"html":"<p>Tempe Volleyball and the Sydney Uni Volleyball Club (USYD) select junior teams to play in the Junior Sydney Volleyball League against other clubs, with qualified coaches, weekly training and club uniforms for rep players.</p><h2>What selected players commit to</h2><ul><li><p>A weekly league game through the season, at Sydney Olympic Park</p></li><li><p>Weekly coached training, which is an essential part of the program</p></li></ul><p>Teams are picked at selection trials before each season. Register your interest below and we’ll be in touch about trial dates.</p><p>Rep players need a <strong>full</strong> Volleyball NSW membership through USYD. <a href=\"https://www.revolutionise.com.au/usyd/registration/\" target=\"_blank\" rel=\"noopener\">Register with Volleyball NSW</a> once selected. All our coaches hold a current Working With Children Check.</p>"}', NULL, NULL, NULL, NULL, 1 WHERE NOT EXISTS (SELECT 1 FROM "leagues" WHERE "id" = '69d527f4-23db-8a7c-a65c-03b6a8c17e67' OR "code" = 'JREP' OR "slug" = 'junior-rep-teams') AND EXISTS (SELECT 1 FROM "categories" WHERE "id" = 'cat_juniors');
