INSERT INTO "audit_log" ("id", "at", "actor_user_id", "action", "target_type", "target_id", "before", "after", "ip") SELECT lower(hex(randomblob(16))), strftime('%Y-%m-%dT%H:%M:%fZ', 'now'), NULL, 'venue.update', 'venue', (SELECT "id" FROM "venues" WHERE "slug" = 'robyn-webster-sports-centre'), '{"directions":null}', '{"directions":"Car: about 15 minutes from the city down King St, Newtown. Turn right onto the Princes Highway; Holbeach Ave is the first left at the traffic lights after the old Harp Hotel. Free parking at the sports centre.\nTrain: T4 Eastern Suburbs & Illawarra Line from Central to Wolli Creek, then a short walk across the Princes Highway to Holbeach Ave.\nBus: the 422 from King St near Newtown Station to Tempe Bus Depot, then a short walk across the Princes Highway to Holbeach Ave.","source":"scripts/content (content map)"}', NULL WHERE EXISTS (SELECT 1 FROM "venues" WHERE "slug" = 'robyn-webster-sports-centre' AND "updated_by" IS NULL AND ("directions" IS NULL OR "directions" = ''));
INSERT INTO "audit_log" ("id", "at", "actor_user_id", "action", "target_type", "target_id", "before", "after", "ip") SELECT lower(hex(randomblob(16))), strftime('%Y-%m-%dT%H:%M:%fZ', 'now'), NULL, 'venue.update', 'venue', (SELECT "id" FROM "venues" WHERE "slug" = 'mlc-school'), '{"directions":null}', '{"directions":"Car: street parking around Rowley St, Grantham St and Park Rd.\nTrain and bus: a 10-minute walk from Burwood Station and nearby bus stops.","source":"scripts/content (content map)"}', NULL WHERE EXISTS (SELECT 1 FROM "venues" WHERE "slug" = 'mlc-school' AND "updated_by" IS NULL AND ("directions" IS NULL OR "directions" = ''));
INSERT INTO "page_revisions" ("id", "page_id", "title", "body", "created_by", "created_at") SELECT '8bfe97ed-6cfc-83bf-9e48-03909d9101ee', "id", 'Welcome to Tempe Volleyball', '{"blocks":[{"type":"paragraph","content":[{"type":"text","text":"Tempe Volleyball runs social mixed leagues, a competitive Super League, and training and development programs for adults and juniors across Sydney’s inner west, in Tempe, Burwood and Five Dock, together with the "},{"type":"text","text":"Sydney Uni Volleyball Club","marks":[{"type":"link","attrs":{"href":"https://www.suvolleyball.com/","target":"_blank"}}]},{"type":"text","text":"."}]},{"type":"paragraph","content":[{"type":"text","text":"Whether you’re completely new to volleyball or coming back after a break, our coaches and competitions give you a relaxed, friendly place to build confidence and enjoy the game."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Leagues"}]},{"type":"paragraph","content":[{"type":"text","text":"Our mixed leagues have an A Division (intermediate to advanced) and a B Division (beginner to intermediate, perfect for new players). Individuals and full teams are welcome: we place players in teams by skill level."}]},{"type":"programmeList","attrs":{"filter":{"categoryIds":["cat_mixed_leagues","cat_super_league"],"kinds":["league"],"enrolmentOpenOnly":false,"enrolment":"any"},"template":null,"order":[],"hidden":[],"overrides":{},"title":null,"linkLines":true,"useSummaryLines":true,"emptyText":null}},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Training and development"}]},{"type":"paragraph","content":[{"type":"text","text":"Coaching for adults (18+) and juniors (12 to 17), from the basics to rep teams."}]},{"type":"programmeList","attrs":{"filter":{"categoryIds":["cat_adult_training","cat_juniors"],"kinds":[],"enrolmentOpenOnly":false,"enrolment":"any"},"template":null,"order":[],"hidden":[],"overrides":{},"title":null,"linkLines":true,"useSummaryLines":true,"emptyText":"Training and junior programs are listed here when their next term or session is set. Contact Michael for details."}},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"How to join"}]},{"type":"paragraph","content":[{"type":"text","text":"See what’s open on the "},{"type":"text","text":"Enrol","marks":[{"type":"link","attrs":{"href":"/enrol"}}]},{"type":"text","text":" page, or "},{"type":"text","text":"contact Michael","marks":[{"type":"link","attrs":{"href":"/contact"}}]},{"type":"text","text":" for help choosing the right program."}]},{"type":"paragraph","content":[{"type":"text","text":"Follow us on "},{"type":"text","text":"Instagram (@tempe.volleyball)","marks":[{"type":"link","attrs":{"href":"https://www.instagram.com/tempe.volleyball/","target":"_blank"}}]},{"type":"text","text":" for news, and see "},{"type":"text","text":"Where we play","marks":[{"type":"link","attrs":{"href":"/where-we-play"}}]},{"type":"text","text":" for directions."}]}],"html":"<p>Tempe Volleyball runs social mixed leagues, a competitive Super League, and training and development programs for adults and juniors across Sydney’s inner west, in Tempe, Burwood and Five Dock, together with the <a href=\"https://www.suvolleyball.com/\" target=\"_blank\" rel=\"noopener\">Sydney Uni Volleyball Club</a>.</p><p>Whether you’re completely new to volleyball or coming back after a break, our coaches and competitions give you a relaxed, friendly place to build confidence and enjoy the game.</p><h2>Leagues</h2><p>Our mixed leagues have an A Division (intermediate to advanced) and a B Division (beginner to intermediate, perfect for new players). Individuals and full teams are welcome: we place players in teams by skill level.</p><h2>Training and development</h2><p>Coaching for adults (18+) and juniors (12 to 17), from the basics to rep teams.</p><h2>How to join</h2><p>See what’s open on the <a href=\"/enrol\">Enrol</a> page, or <a href=\"/contact\">contact Michael</a> for help choosing the right program.</p><p>Follow us on <a href=\"https://www.instagram.com/tempe.volleyball/\" target=\"_blank\" rel=\"noopener\">Instagram (@tempe.volleyball)</a> for news, and see <a href=\"/where-we-play\">Where we play</a> for directions.</p>"}', NULL, strftime('%Y-%m-%dT%H:%M:%fZ', 'now', '-1 second') FROM "pages" WHERE "pages"."path" = '/' AND "pages"."wp_id" = 3465 AND "pages"."title" = 'Welcome to Tempe Volleyball!' AND "pages"."updated_by" IS NULL AND NOT EXISTS (SELECT 1 FROM "page_revisions" r WHERE r."page_id" = "pages"."id" AND r."id" NOT IN ('8bfe97ed-6cfc-83bf-9e48-03909d9101ee', '493eb985-a076-886f-a328-fd2dcc475587')) AND "pages"."status" = 'published' AND NOT EXISTS (SELECT 1 FROM "page_revisions" WHERE "id" = '8bfe97ed-6cfc-83bf-9e48-03909d9101ee') AND NOT EXISTS (SELECT 1 FROM "page_revisions" WHERE "id" = '493eb985-a076-886f-a328-fd2dcc475587');
INSERT INTO "page_revisions" ("id", "page_id", "title", "body", "created_by", "created_at") SELECT '493eb985-a076-886f-a328-fd2dcc475587', "id", "title", "body", "updated_by", strftime('%Y-%m-%dT%H:%M:%fZ', 'now') FROM "pages" WHERE "pages"."path" = '/' AND "pages"."wp_id" = 3465 AND "pages"."title" = 'Welcome to Tempe Volleyball!' AND "pages"."updated_by" IS NULL AND NOT EXISTS (SELECT 1 FROM "page_revisions" r WHERE r."page_id" = "pages"."id" AND r."id" NOT IN ('8bfe97ed-6cfc-83bf-9e48-03909d9101ee', '493eb985-a076-886f-a328-fd2dcc475587')) AND "pages"."status" = 'published' AND NOT EXISTS (SELECT 1 FROM "page_revisions" WHERE "id" = '493eb985-a076-886f-a328-fd2dcc475587') AND EXISTS (SELECT 1 FROM "page_revisions" WHERE "id" = '8bfe97ed-6cfc-83bf-9e48-03909d9101ee' AND "page_id" = "pages"."id");
INSERT INTO "page_revisions" ("id", "page_id", "title", "body", "created_by", "created_at") SELECT 'a93e1ba0-d261-86af-843e-0e4c298ff5a0', "id", 'About Tempe Volleyball', '{"blocks":[{"type":"paragraph","content":[{"type":"text","text":"Founded in 2005, Tempe Volleyball is one of the longest-running volleyball clubs in Sydney, built on a simple mission: to introduce more people to volleyball and make it accessible to players of all ages and skill levels."}]},{"type":"paragraph","content":[{"type":"text","text":"What began as a small community initiative has grown into a volleyball hub with mixed social competitions, development programs for beginners through to advanced players, and pathways for juniors and adults. We’ve welcomed thousands of players into a friendly, supportive and inclusive environment."}]},{"type":"paragraph","content":[{"type":"text","text":"If you’re looking to start playing volleyball or return to it, Tempe Volleyball is the perfect place to begin."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Find out more"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Where we play","marks":[{"type":"link","attrs":{"href":"/where-we-play"}}]},{"type":"text","text":": venues and directions"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"League rules","marks":[{"type":"link","attrs":{"href":"/rules"}}]}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Frequently asked questions","marks":[{"type":"link","attrs":{"href":"/faq"}}]}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Contact us","marks":[{"type":"link","attrs":{"href":"/contact"}}]}]}]}]}],"html":"<p>Founded in 2005, Tempe Volleyball is one of the longest-running volleyball clubs in Sydney, built on a simple mission: to introduce more people to volleyball and make it accessible to players of all ages and skill levels.</p><p>What began as a small community initiative has grown into a volleyball hub with mixed social competitions, development programs for beginners through to advanced players, and pathways for juniors and adults. We’ve welcomed thousands of players into a friendly, supportive and inclusive environment.</p><p>If you’re looking to start playing volleyball or return to it, Tempe Volleyball is the perfect place to begin.</p><h2>Find out more</h2><ul><li><p><a href=\"/where-we-play\">Where we play</a>: venues and directions</p></li><li><p><a href=\"/rules\">League rules</a></p></li><li><p><a href=\"/faq\">Frequently asked questions</a></p></li><li><p><a href=\"/contact\">Contact us</a></p></li></ul>"}', NULL, strftime('%Y-%m-%dT%H:%M:%fZ', 'now', '-1 second') FROM "pages" WHERE "pages"."path" = '/about-tempe-vb' AND "pages"."wp_id" = 6261 AND "pages"."title" = 'About Tempe VB' AND "pages"."updated_by" IS NULL AND NOT EXISTS (SELECT 1 FROM "page_revisions" r WHERE r."page_id" = "pages"."id" AND r."id" NOT IN ('a93e1ba0-d261-86af-843e-0e4c298ff5a0', '1bdf0420-ceba-8e93-8879-e409a5369df2')) AND "pages"."status" = 'published' AND NOT EXISTS (SELECT 1 FROM "page_revisions" WHERE "id" = 'a93e1ba0-d261-86af-843e-0e4c298ff5a0') AND NOT EXISTS (SELECT 1 FROM "page_revisions" WHERE "id" = '1bdf0420-ceba-8e93-8879-e409a5369df2');
INSERT INTO "page_revisions" ("id", "page_id", "title", "body", "created_by", "created_at") SELECT '1bdf0420-ceba-8e93-8879-e409a5369df2', "id", "title", "body", "updated_by", strftime('%Y-%m-%dT%H:%M:%fZ', 'now') FROM "pages" WHERE "pages"."path" = '/about-tempe-vb' AND "pages"."wp_id" = 6261 AND "pages"."title" = 'About Tempe VB' AND "pages"."updated_by" IS NULL AND NOT EXISTS (SELECT 1 FROM "page_revisions" r WHERE r."page_id" = "pages"."id" AND r."id" NOT IN ('a93e1ba0-d261-86af-843e-0e4c298ff5a0', '1bdf0420-ceba-8e93-8879-e409a5369df2')) AND "pages"."status" = 'published' AND NOT EXISTS (SELECT 1 FROM "page_revisions" WHERE "id" = '1bdf0420-ceba-8e93-8879-e409a5369df2') AND EXISTS (SELECT 1 FROM "page_revisions" WHERE "id" = 'a93e1ba0-d261-86af-843e-0e4c298ff5a0' AND "page_id" = "pages"."id");
INSERT INTO "page_revisions" ("id", "page_id", "title", "body", "created_by", "created_at") SELECT '06f69749-b50c-8cca-b42b-fdaa60398e91', "id", 'Where we play', '{"blocks":[{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Robyn Webster Sports Centre, Tempe"}]},{"type":"paragraph","content":[{"type":"text","text":"Holbeach Ave, Tempe NSW 2044."}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"By car"}]},{"type":"paragraph","content":[{"type":"text","text":"About 15 minutes from the city down King St, Newtown. Turn right onto the Princes Highway; Holbeach Ave is the first left at the traffic lights after the old Harp Hotel. There’s free parking at the sports centre."}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"By train"}]},{"type":"paragraph","content":[{"type":"text","text":"Take the T4 Eastern Suburbs & Illawarra Line from Central to Wolli Creek, then walk across the Princes Highway to Holbeach Ave."}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"By bus"}]},{"type":"paragraph","content":[{"type":"text","text":"Take the 422 from King St near Newtown Station to Tempe Bus Depot, then walk across the Princes Highway to Holbeach Ave."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"MLC School, Burwood"}]},{"type":"paragraph","content":[{"type":"text","text":"Rowley St, Burwood NSW 2134."}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"By car"}]},{"type":"paragraph","content":[{"type":"text","text":"Street parking around Rowley St, Grantham St and Park Rd."}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"By train or bus"}]},{"type":"paragraph","content":[{"type":"text","text":"A 10-minute walk from Burwood Station and nearby bus stops."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Five Dock Leisure Centre"}]},{"type":"paragraph","content":[{"type":"text","text":"William St, Five Dock NSW 2046."}]}],"html":"<h2>Robyn Webster Sports Centre, Tempe</h2><p>Holbeach Ave, Tempe NSW 2044.</p><h3>By car</h3><p>About 15 minutes from the city down King St, Newtown. Turn right onto the Princes Highway; Holbeach Ave is the first left at the traffic lights after the old Harp Hotel. There’s free parking at the sports centre.</p><h3>By train</h3><p>Take the T4 Eastern Suburbs &amp; Illawarra Line from Central to Wolli Creek, then walk across the Princes Highway to Holbeach Ave.</p><h3>By bus</h3><p>Take the 422 from King St near Newtown Station to Tempe Bus Depot, then walk across the Princes Highway to Holbeach Ave.</p><h2>MLC School, Burwood</h2><p>Rowley St, Burwood NSW 2134.</p><h3>By car</h3><p>Street parking around Rowley St, Grantham St and Park Rd.</p><h3>By train or bus</h3><p>A 10-minute walk from Burwood Station and nearby bus stops.</p><h2>Five Dock Leisure Centre</h2><p>William St, Five Dock NSW 2046.</p>"}', NULL, strftime('%Y-%m-%dT%H:%M:%fZ', 'now', '-1 second') FROM "pages" WHERE "pages"."path" = '/where-we-play' AND "pages"."wp_id" = 694 AND "pages"."title" = 'WHERE WE PLAY' AND "pages"."updated_by" IS NULL AND NOT EXISTS (SELECT 1 FROM "page_revisions" r WHERE r."page_id" = "pages"."id" AND r."id" NOT IN ('06f69749-b50c-8cca-b42b-fdaa60398e91', 'e138c508-8d9b-8abc-91b8-d904232d35d5')) AND "pages"."status" = 'published' AND NOT EXISTS (SELECT 1 FROM "page_revisions" WHERE "id" = '06f69749-b50c-8cca-b42b-fdaa60398e91') AND NOT EXISTS (SELECT 1 FROM "page_revisions" WHERE "id" = 'e138c508-8d9b-8abc-91b8-d904232d35d5');
