INSERT INTO "page_revisions" ("id", "page_id", "title", "body", "created_by", "created_at") SELECT 'f9ee6d8a-73eb-8294-8ac5-484e8e597340', "id", 'Contact', '{"blocks":[{"type":"paragraph","content":[{"type":"text","text":"Questions about a league, a program or your enrolment? Get in touch with Michael:"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Email "},{"type":"text","text":"tempevb@gmail.com","marks":[{"type":"link","attrs":{"href":"mailto:tempevb@gmail.com"}}]},{"type":"text","text":" or "},{"type":"text","text":"m.mouhajer@bigpond.com","marks":[{"type":"link","attrs":{"href":"mailto:m.mouhajer@bigpond.com"}}]}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Phone "},{"type":"text","text":"0414 911 544","marks":[{"type":"link","attrs":{"href":"tel:+61414911544"}}]}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"Ready to play? Enrol on the "},{"type":"text","text":"Enrol","marks":[{"type":"link","attrs":{"href":"/enrol"}}]},{"type":"text","text":" page."}]},{"type":"paragraph","content":[{"type":"text","text":"Directions to each venue are on "},{"type":"text","text":"Where we play","marks":[{"type":"link","attrs":{"href":"/where-we-play"}}]},{"type":"text","text":"."}]}],"html":"<p>Questions about a league, a program or your enrolment? Get in touch with Michael:</p><ul><li><p>Email <a href=\"mailto:tempevb@gmail.com\">tempevb@gmail.com</a> or <a href=\"mailto:m.mouhajer@bigpond.com\">m.mouhajer@bigpond.com</a></p></li><li><p>Phone <a href=\"tel:+61414911544\">0414 911 544</a></p></li></ul><p>Ready to play? Enrol on the <a href=\"/enrol\">Enrol</a> page.</p><p>Directions to each venue are on <a href=\"/where-we-play\">Where we play</a>.</p>"}', NULL, strftime('%Y-%m-%dT%H:%M:%fZ', 'now', '-1 second') FROM "pages" WHERE "pages"."path" = '/contact' AND "pages"."wp_id" = 62 AND "pages"."title" = 'CONTACT' AND "pages"."updated_by" IS NULL AND NOT EXISTS (SELECT 1 FROM "page_revisions" r WHERE r."page_id" = "pages"."id" AND r."id" NOT IN ('f9ee6d8a-73eb-8294-8ac5-484e8e597340', '5cb46ee0-38be-89dc-9008-3bbd7444de7b')) AND "pages"."status" = 'published' AND NOT EXISTS (SELECT 1 FROM "page_revisions" WHERE "id" = 'f9ee6d8a-73eb-8294-8ac5-484e8e597340') AND NOT EXISTS (SELECT 1 FROM "page_revisions" WHERE "id" = '5cb46ee0-38be-89dc-9008-3bbd7444de7b');
