INSERT INTO "page_revisions" ("id", "page_id", "title", "body", "created_by", "created_at") SELECT 'b3b7fcc3-a068-810b-9b9e-d4ea3cb527b0', "id", 'League rules', '{"blocks":[{"type":"paragraph","content":[{"type":"text","text":"How our social leagues run. The "},{"type":"text","text":"Super League","marks":[{"type":"link","attrs":{"href":"/leagues/tvsl"}}]},{"type":"text","text":" has its own format and Volleyball NSW referees, so it has no team duty."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Matches and points"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Each match is two sets, so a draw is possible"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Ladder points: win 3, draw 2, loss 1"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"The duty team does the coin toss during the warm-up"}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Duty"}]},{"type":"paragraph","content":[{"type":"text","text":"Teams referee each other’s matches. A duty team needs "},{"type":"text","text":"five people","marks":[{"type":"bold"}]},{"type":"text","text":": 1st referee, 2nd referee, scorer and two line judges. You’ll see your duties in the fixtures."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Match schedule (8–10pm nights)"}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"First matches, 8:00–9:00pm"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"8:00–8:05: duty team sets up"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"8:05–8:15: warm-up"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"8:15–9:00: play"}]}]}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"Second matches, 9:00–10:00pm"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"9:00–9:10: warm-up"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"9:10–9:55: play"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"9:55–10:00: duty team packs up"}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Promotion and relegation"}]},{"type":"paragraph","content":[{"type":"text","text":"At the end of a season we may promote the B Division winners to A Division, and move the last-placed A Division team to B Division."}]}],"html":"<p>How our social leagues run. The <a href=\"/leagues/tvsl\">Super League</a> has its own format and Volleyball NSW referees, so it has no team duty.</p><h2>Matches and points</h2><ul><li><p>Each match is two sets, so a draw is possible</p></li><li><p>Ladder points: win 3, draw 2, loss 1</p></li><li><p>The duty team does the coin toss during the warm-up</p></li></ul><h2>Duty</h2><p>Teams referee each other’s matches. A duty team needs <strong>five people</strong>: 1st referee, 2nd referee, scorer and two line judges. You’ll see your duties in the fixtures.</p><h2>Match schedule (8–10pm nights)</h2><h3>First matches, 8:00–9:00pm</h3><ul><li><p>8:00–8:05: duty team sets up</p></li><li><p>8:05–8:15: warm-up</p></li><li><p>8:15–9:00: play</p></li></ul><h3>Second matches, 9:00–10:00pm</h3><ul><li><p>9:00–9:10: warm-up</p></li><li><p>9:10–9:55: play</p></li><li><p>9:55–10:00: duty team packs up</p></li></ul><h2>Promotion and relegation</h2><p>At the end of a season we may promote the B Division winners to A Division, and move the last-placed A Division team to B Division.</p>"}', NULL, strftime('%Y-%m-%dT%H:%M:%fZ', 'now', '-1 second') FROM "pages" WHERE "pages"."path" = '/rules' AND "pages"."wp_id" = 127 AND "pages"."title" = 'RULES' AND "pages"."updated_by" IS NULL AND NOT EXISTS (SELECT 1 FROM "page_revisions" r WHERE r."page_id" = "pages"."id" AND r."id" NOT IN ('b3b7fcc3-a068-810b-9b9e-d4ea3cb527b0', 'ced8435d-5847-8841-8bb7-8da09c3ca72c')) AND "pages"."status" = 'published' AND NOT EXISTS (SELECT 1 FROM "page_revisions" WHERE "id" = 'b3b7fcc3-a068-810b-9b9e-d4ea3cb527b0') AND NOT EXISTS (SELECT 1 FROM "page_revisions" WHERE "id" = 'ced8435d-5847-8841-8bb7-8da09c3ca72c');
INSERT INTO "page_revisions" ("id", "page_id", "title", "body", "created_by", "created_at") SELECT 'ced8435d-5847-8841-8bb7-8da09c3ca72c', "id", "title", "body", "updated_by", strftime('%Y-%m-%dT%H:%M:%fZ', 'now') FROM "pages" WHERE "pages"."path" = '/rules' AND "pages"."wp_id" = 127 AND "pages"."title" = 'RULES' AND "pages"."updated_by" IS NULL AND NOT EXISTS (SELECT 1 FROM "page_revisions" r WHERE r."page_id" = "pages"."id" AND r."id" NOT IN ('b3b7fcc3-a068-810b-9b9e-d4ea3cb527b0', 'ced8435d-5847-8841-8bb7-8da09c3ca72c')) AND "pages"."status" = 'published' AND NOT EXISTS (SELECT 1 FROM "page_revisions" WHERE "id" = 'ced8435d-5847-8841-8bb7-8da09c3ca72c') AND EXISTS (SELECT 1 FROM "page_revisions" WHERE "id" = 'b3b7fcc3-a068-810b-9b9e-d4ea3cb527b0' AND "page_id" = "pages"."id");
INSERT INTO "page_revisions" ("id", "page_id", "title", "body", "created_by", "created_at") SELECT 'e8dad506-0199-8115-8060-8759fd1d158a', "id", 'Frequently asked questions', '{"blocks":[{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"What programs do you offer?"}]},{"type":"paragraph","content":[{"type":"text","text":"Weekly social "},{"type":"text","text":"mixed leagues","marks":[{"type":"link","attrs":{"href":"/mixed-leagues"}}]},{"type":"text","text":", a competitive "},{"type":"text","text":"Super League","marks":[{"type":"link","attrs":{"href":"/super-league"}}]},{"type":"text","text":", and training and development sessions for "},{"type":"text","text":"adults","marks":[{"type":"link","attrs":{"href":"/adult-training"}}]},{"type":"text","text":" and "},{"type":"text","text":"juniors","marks":[{"type":"link","attrs":{"href":"/juniors"}}]},{"type":"text","text":" throughout the year. We welcome beginners and players just starting out."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Can beginners join?"}]},{"type":"paragraph","content":[{"type":"text","text":"Yes. Every program welcomes beginners, and the leagues’ B Division is ideal for new players. "},{"type":"text","text":"Contact Michael","marks":[{"type":"link","attrs":{"href":"/contact"}}]},{"type":"text","text":" if you’d like help choosing a day or program."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Where do you play?"}]},{"type":"paragraph","content":[{"type":"text","text":"In Tempe, Burwood and Five Dock: see "},{"type":"text","text":"Where we play","marks":[{"type":"link","attrs":{"href":"/where-we-play"}}]},{"type":"text","text":". Each league and program page shows its venue, and we post changes on "},{"type":"text","text":"Instagram","marks":[{"type":"link","attrs":{"href":"https://www.instagram.com/tempe.volleyball/","target":"_blank"}}]},{"type":"text","text":"."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Do I need a team to join?"}]},{"type":"paragraph","content":[{"type":"text","text":"No. Enter on your own and we’ll place you in a team that suits your level."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"How do I enrol?"}]},{"type":"paragraph","content":[{"type":"text","text":"Pick a league or program on the "},{"type":"text","text":"Enrol","marks":[{"type":"link","attrs":{"href":"/enrol"}}]},{"type":"text","text":" page and fill in its form. We’ll confirm your spot by email."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Do I need a Volleyball NSW membership?"}]},{"type":"paragraph","content":[{"type":"text","text":"Yes, every player needs at least a recreational membership through our club (USYD). Wait until your spot is confirmed, then "},{"type":"text","text":"register with Volleyball NSW","marks":[{"type":"link","attrs":{"href":"https://www.revolutionise.com.au/usyd/registration/","target":"_blank"}}]},{"type":"text","text":"."}]}],"html":"<h2>What programs do you offer?</h2><p>Weekly social <a href=\"/mixed-leagues\">mixed leagues</a>, a competitive <a href=\"/super-league\">Super League</a>, and training and development sessions for <a href=\"/adult-training\">adults</a> and <a href=\"/juniors\">juniors</a> throughout the year. We welcome beginners and players just starting out.</p><h2>Can beginners join?</h2><p>Yes. Every program welcomes beginners, and the leagues’ B Division is ideal for new players. <a href=\"/contact\">Contact Michael</a> if you’d like help choosing a day or program.</p><h2>Where do you play?</h2><p>In Tempe, Burwood and Five Dock: see <a href=\"/where-we-play\">Where we play</a>. Each league and program page shows its venue, and we post changes on <a href=\"https://www.instagram.com/tempe.volleyball/\" target=\"_blank\" rel=\"noopener\">Instagram</a>.</p><h2>Do I need a team to join?</h2><p>No. Enter on your own and we’ll place you in a team that suits your level.</p><h2>How do I enrol?</h2><p>Pick a league or program on the <a href=\"/enrol\">Enrol</a> page and fill in its form. We’ll confirm your spot by email.</p><h2>Do I need a Volleyball NSW membership?</h2><p>Yes, every player needs at least a recreational membership through our club (USYD). Wait until your spot is confirmed, then <a href=\"https://www.revolutionise.com.au/usyd/registration/\" target=\"_blank\" rel=\"noopener\">register with Volleyball NSW</a>.</p>"}', NULL, strftime('%Y-%m-%dT%H:%M:%fZ', 'now', '-1 second') FROM "pages" WHERE "pages"."path" = '/faq' AND "pages"."wp_id" = 6266 AND "pages"."title" = 'FAQ' AND "pages"."updated_by" IS NULL AND NOT EXISTS (SELECT 1 FROM "page_revisions" r WHERE r."page_id" = "pages"."id" AND r."id" NOT IN ('e8dad506-0199-8115-8060-8759fd1d158a', '4aba701e-e94c-83dd-8ebb-56cc5d7d3657')) AND "pages"."status" = 'published' AND NOT EXISTS (SELECT 1 FROM "page_revisions" WHERE "id" = 'e8dad506-0199-8115-8060-8759fd1d158a') AND NOT EXISTS (SELECT 1 FROM "page_revisions" WHERE "id" = '4aba701e-e94c-83dd-8ebb-56cc5d7d3657');
INSERT INTO "page_revisions" ("id", "page_id", "title", "body", "created_by", "created_at") SELECT '4aba701e-e94c-83dd-8ebb-56cc5d7d3657', "id", "title", "body", "updated_by", strftime('%Y-%m-%dT%H:%M:%fZ', 'now') FROM "pages" WHERE "pages"."path" = '/faq' AND "pages"."wp_id" = 6266 AND "pages"."title" = 'FAQ' AND "pages"."updated_by" IS NULL AND NOT EXISTS (SELECT 1 FROM "page_revisions" r WHERE r."page_id" = "pages"."id" AND r."id" NOT IN ('e8dad506-0199-8115-8060-8759fd1d158a', '4aba701e-e94c-83dd-8ebb-56cc5d7d3657')) AND "pages"."status" = 'published' AND NOT EXISTS (SELECT 1 FROM "page_revisions" WHERE "id" = '4aba701e-e94c-83dd-8ebb-56cc5d7d3657') AND EXISTS (SELECT 1 FROM "page_revisions" WHERE "id" = 'e8dad506-0199-8115-8060-8759fd1d158a' AND "page_id" = "pages"."id");
INSERT INTO "pages" ("id", "path", "title", "meta_description", "template", "body", "status") SELECT '8fc446cb-1de7-84d6-b42d-d5cb30277b6a', '/enrol', 'Enrol', 'Enrol in Tempe Volleyball’s social leagues, Super League, training and junior programs in Sydney.', 'content', '{"blocks":[{"type":"paragraph","content":[{"type":"text","text":"Pick a league, training session or program below and fill in its form. Leagues take whole teams and individual players: enter on your own and we’ll place you in a team that suits your level."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"What happens next"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"We email you to confirm your spot. If it’s full, you join the waitlist, and we email you if a spot comes up."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Once your spot is confirmed, pay by PayID to 0414 911 544, with your name (or your child’s) as the reference."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Then register with Volleyball NSW if you haven’t already: every player needs at least a recreational membership through our club (USYD). "},{"type":"text","text":"Register with Volleyball NSW","marks":[{"type":"link","attrs":{"href":"https://www.revolutionise.com.au/usyd/registration/","target":"_blank"}}]},{"type":"text","text":". Already a member through another club? Choose “Renew” and add USYD to your profile."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"Questions? "},{"type":"text","text":"Contact Michael","marks":[{"type":"link","attrs":{"href":"/contact"}}]},{"type":"text","text":"."}]}],"html":"<p>Pick a league, training session or program below and fill in its form. Leagues take whole teams and individual players: enter on your own and we’ll place you in a team that suits your level.</p><h2>What happens next</h2><ul><li><p>We email you to confirm your spot. If it’s full, you join the waitlist, and we email you if a spot comes up.</p></li><li><p>Once your spot is confirmed, pay by PayID to 0414 911 544, with your name (or your child’s) as the reference.</p></li><li><p>Then register with Volleyball NSW if you haven’t already: every player needs at least a recreational membership through our club (USYD). <a href=\"https://www.revolutionise.com.au/usyd/registration/\" target=\"_blank\" rel=\"noopener\">Register with Volleyball NSW</a>. Already a member through another club? Choose “Renew” and add USYD to your profile.</p></li></ul><p>Questions? <a href=\"/contact\">Contact Michael</a>.</p>"}', 'draft' WHERE NOT EXISTS (SELECT 1 FROM "pages" WHERE "path" = '/enrol' OR "id" = '8fc446cb-1de7-84d6-b42d-d5cb30277b6a');
