UPDATE "leagues" SET "description" = '{"blocks":[{"type":"paragraph","content":[{"type":"text","text":"The Tempe Volleyball Super League (TVSL) is for teams serious about progressing beyond social volleyball. It’s a structured, competitive league that follows Volleyball NSW’s endorsement framework for the Sydney Volleyball League (SVL), with men’s and women’s divisions at SVL Division 3/4 level."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Promotion pathway"}]},{"type":"paragraph","content":[{"type":"text","text":"Division 3 champions are nominated for the Volleyball NSW Sydney Volleyball League Promotion Day. The winning team there can play in Division 2 of the Sydney Volleyball League the following year."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Format"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"An eight-week round robin, then semi-finals and a grand final"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Each match has a 90-minute court slot: a 10-minute warm-up and 80 minutes of play"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Best of five sets: sets 1–4 to 25 points, set 5 to 15"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Round-robin matches are timed; the grand final is untimed"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Matches are run by qualified referees or officials recognised by Volleyball NSW, depending on availability. There’s no team duty."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Fees"}]},{"type":"paragraph","content":[{"type":"text","text":"Team entry fees cover the officials, court hire, finals and running the league."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Entering a team"}]},{"type":"paragraph","content":[{"type":"text","text":"Enter your team with the form below when entries are open. Entries close before the season starts, or earlier if the league fills, and a place is confirmed once the entry fee is paid in full."}]},{"type":"paragraph","content":[{"type":"text","text":"Every player needs a current Volleyball NSW recreational membership, through our club (Sydney Uni, USYD). "},{"type":"text","text":"Register with Volleyball NSW","marks":[{"type":"link","attrs":{"href":"https://www.revolutionise.com.au/usyd/registration/","target":"_blank"}}]},{"type":"text","text":" once your spot is confirmed. Already a member through another club? Choose “Renew” on that page and add USYD to your profile."}]}],"html":"<p>The Tempe Volleyball Super League (TVSL) is for teams serious about progressing beyond social volleyball. It’s a structured, competitive league that follows Volleyball NSW’s endorsement framework for the Sydney Volleyball League (SVL), with men’s and women’s divisions at SVL Division 3/4 level.</p><h2>Promotion pathway</h2><p>Division 3 champions are nominated for the Volleyball NSW Sydney Volleyball League Promotion Day. The winning team there can play in Division 2 of the Sydney Volleyball League the following year.</p><h2>Format</h2><ul><li><p>An eight-week round robin, then semi-finals and a grand final</p></li><li><p>Each match has a 90-minute court slot: a 10-minute warm-up and 80 minutes of play</p></li><li><p>Best of five sets: sets 1–4 to 25 points, set 5 to 15</p></li><li><p>Round-robin matches are timed; the grand final is untimed</p></li><li><p>Matches are run by qualified referees or officials recognised by Volleyball NSW, depending on availability. There’s no team duty.</p></li></ul><h2>Fees</h2><p>Team entry fees cover the officials, court hire, finals and running the league.</p><h2>Entering a team</h2><p>Enter your team with the form below when entries are open. Entries close before the season starts, or earlier if the league fills, and a place is confirmed once the entry fee is paid in full.</p><p>Every player needs a current Volleyball NSW recreational membership, through our club (Sydney Uni, USYD). <a href=\"https://www.revolutionise.com.au/usyd/registration/\" target=\"_blank\" rel=\"noopener\">Register with Volleyball NSW</a> once your spot is confirmed. Already a member through another club? Choose “Renew” on that page and add USYD to your profile.</p>"}', "updated_at" = strftime('%Y-%m-%dT%H:%M:%fZ', 'now') WHERE "code" = 'TVSL' AND "kind" = 'league' AND "updated_by" IS NULL AND json_extract("description", '$.html') = '' AND json_array_length(json_extract("description", '$.blocks')) = 0;
UPDATE "categories" SET "intro" = '{"blocks":[{"type":"paragraph","content":[{"type":"text","text":"Our mixed social leagues run on several nights of the week (each one is listed below). They’re relaxed, friendly and a good way to get some exercise and meet people, whether you’re new to volleyball or coming back to it."}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"A Division","marks":[{"type":"bold"}]},{"type":"text","text":": intermediate to advanced"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"B Division","marks":[{"type":"bold"}]},{"type":"text","text":": beginner to intermediate, ideal for new players"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Matches are two sets, so draws happen. Teams take turns refereeing each other (duty)."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Seasons run every quarter, with finals at the end"}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"Enter as a team or on your own: we place individual players in a team that suits their level. Read the "},{"type":"text","text":"league rules","marks":[{"type":"link","attrs":{"href":"/rules"}}]},{"type":"text","text":" before your first night."}]}],"html":"<p>Our mixed social leagues run on several nights of the week (each one is listed below). They’re relaxed, friendly and a good way to get some exercise and meet people, whether you’re new to volleyball or coming back to it.</p><ul><li><p><strong>A Division</strong>: intermediate to advanced</p></li><li><p><strong>B Division</strong>: beginner to intermediate, ideal for new players</p></li><li><p>Matches are two sets, so draws happen. Teams take turns refereeing each other (duty).</p></li><li><p>Seasons run every quarter, with finals at the end</p></li></ul><p>Enter as a team or on your own: we place individual players in a team that suits their level. Read the <a href=\"/rules\">league rules</a> before your first night.</p>"}', "updated_at" = strftime('%Y-%m-%dT%H:%M:%fZ', 'now') WHERE "id" = 'cat_mixed_leagues' AND "updated_by" IS NULL AND json_extract("intro", '$.html') = '' AND json_array_length(json_extract("intro", '$.blocks')) = 0;
UPDATE "categories" SET "intro" = '{"blocks":[{"type":"paragraph","content":[{"type":"text","text":"The Tempe Volleyball Super League (TVSL) is our competitive league, endorsed by Volleyball NSW, for teams working towards the Sydney Volleyball League. Matches are best of five sets with Volleyball NSW referees."}]}],"html":"<p>The Tempe Volleyball Super League (TVSL) is our competitive league, endorsed by Volleyball NSW, for teams working towards the Sydney Volleyball League. Matches are best of five sets with Volleyball NSW referees.</p>"}', "updated_at" = strftime('%Y-%m-%dT%H:%M:%fZ', 'now') WHERE "id" = 'cat_super_league' AND "updated_by" IS NULL AND json_extract("intro", '$.html') = '' AND json_array_length(json_extract("intro", '$.blocks')) = 0;
UPDATE "categories" SET "intro" = '{"blocks":[{"type":"paragraph","content":[{"type":"text","text":"Volleyball for players aged 12 to 17, from first-timers learning the basics to rep teams playing in the Junior Sydney Volleyball League. All our coaches hold a current Working With Children Check."}]}],"html":"<p>Volleyball for players aged 12 to 17, from first-timers learning the basics to rep teams playing in the Junior Sydney Volleyball League. All our coaches hold a current Working With Children Check.</p>"}', "updated_at" = strftime('%Y-%m-%dT%H:%M:%fZ', 'now') WHERE "id" = 'cat_juniors' AND "updated_by" IS NULL AND json_extract("intro", '$.html') = '' AND json_array_length(json_extract("intro", '$.blocks')) = 0;
UPDATE "categories" SET "intro" = '{"blocks":[{"type":"paragraph","content":[{"type":"text","text":"Coached sessions and court time for adults, whether you’ve never played or want to sharpen your game before joining a league. No team needed: come on your own."}]}],"html":"<p>Coached sessions and court time for adults, whether you’ve never played or want to sharpen your game before joining a league. No team needed: come on your own.</p>"}', "updated_at" = strftime('%Y-%m-%dT%H:%M:%fZ', 'now') WHERE "id" = 'cat_adult_training' AND "updated_by" IS NULL AND json_extract("intro", '$.html') = '' AND json_array_length(json_extract("intro", '$.blocks')) = 0;
UPDATE "venues" SET "directions" = 'Car: about 15 minutes from the city down King St, Newtown. Turn right onto the Princes Highway; Holbeach Ave is the first left at the traffic lights after the old Harp Hotel. Free parking at the sports centre.
Train: T4 Eastern Suburbs & Illawarra Line from Central to Wolli Creek, then a short walk across the Princes Highway to Holbeach Ave.
Bus: the 422 from King St near Newtown Station to Tempe Bus Depot, then a short walk across the Princes Highway to Holbeach Ave.', "updated_at" = strftime('%Y-%m-%dT%H:%M:%fZ', 'now') WHERE "slug" = 'robyn-webster-sports-centre' AND "updated_by" IS NULL AND ("directions" IS NULL OR "directions" = '');
